UPDATE ifj_runtime_command command_record JOIN ifj_trigger_work_item work_item ON work_item.trigger_id = command_record.trigger_id SET command_record.status = #{status}, command_record.result_message = #{resultMessage}, command_record.processing_owner = NULL, command_record.processing_token = NULL, command_record.processing_fence = NULL, command_record.processed_at = CURRENT_TIMESTAMP(3), command_record.update_time = CURRENT_TIMESTAMP(3) WHERE command_record.request_id = #{requestId} AND command_record.status = 'PROCESSING' AND command_record.processing_token = #{processingToken} AND command_record.processing_fence = #{fenceToken} AND work_item.fence_token = command_record.processing_fence AND ( (work_item.status = 'CLAIMED' AND work_item.lease_owner = command_record.processing_owner AND work_item.lease_deadline > CURRENT_TIMESTAMP(3))
OR ( command_record.command_type = 'STOP' AND work_item.status = 'COMPLETED' AND work_item.root_instance_id = command_record.root_instance_id AND EXISTS ( SELECT 1 FROM ifj_instance terminal_instance JOIN ifj_instance terminal_root ON terminal_root.id = command_record.root_instance_id WHERE terminal_instance.id = command_record.instance_id AND terminal_instance.status IN ('SUCCESS', 'FAILED', 'STOPPED', 'TIMED_OUT', 'SKIPPED') AND terminal_root.status IN ('SUCCESS', 'FAILED', 'STOPPED', 'TIMED_OUT', 'SKIPPED') AND terminal_instance.execution_fence = command_record.processing_fence AND terminal_root.execution_fence = command_record.processing_fence ) )
)

UPDATE ifj_runtime_command command_record SET status = #{status}, result_message = #{resultMessage}, processing_owner = NULL, processing_token = NULL, processing_fence = NULL, processed_at = CURRENT_TIMESTAMP(3), update_time = CURRENT_TIMESTAMP(3) FROM ifj_trigger_work_item work_item WHERE work_item.trigger_id = command_record.trigger_id AND command_record.request_id = #{requestId} AND command_record.status = 'PROCESSING' AND command_record.processing_token = #{processingToken} AND command_record.processing_fence = #{fenceToken} AND work_item.fence_token = command_record.processing_fence AND ( (work_item.status = 'CLAIMED' AND work_item.lease_owner = command_record.processing_owner AND work_item.lease_deadline > CURRENT_TIMESTAMP(3))
OR ( command_record.command_type = 'STOP' AND work_item.status = 'COMPLETED' AND work_item.root_instance_id = command_record.root_instance_id AND EXISTS ( SELECT 1 FROM ifj_instance terminal_instance JOIN ifj_instance terminal_root ON terminal_root.id = command_record.root_instance_id WHERE terminal_instance.id = command_record.instance_id AND terminal_instance.status IN ('SUCCESS', 'FAILED', 'STOPPED', 'TIMED_OUT', 'SKIPPED') AND terminal_root.status IN ('SUCCESS', 'FAILED', 'STOPPED', 'TIMED_OUT', 'SKIPPED') AND terminal_instance.execution_fence = command_record.processing_fence AND terminal_root.execution_fence = command_record.processing_fence ) )
)

UPDATE ifj_runtime_command AS command_record SET status = #{status}, result_message = #{resultMessage}, processing_owner = NULL, processing_token = NULL, processing_fence = NULL, processed_at = strftime('%Y-%m-%d %H:%M:%f','now'), update_time = strftime('%Y-%m-%d %H:%M:%f','now') FROM ifj_trigger_work_item work_item WHERE work_item.trigger_id = command_record.trigger_id AND command_record.request_id = #{requestId} AND command_record.status = 'PROCESSING' AND command_record.processing_token = #{processingToken} AND command_record.processing_fence = #{fenceToken} AND work_item.fence_token = command_record.processing_fence AND ( (work_item.status = 'CLAIMED' AND work_item.lease_owner = command_record.processing_owner AND work_item.lease_deadline > strftime('%Y-%m-%d %H:%M:%f','now'))
OR ( command_record.command_type = 'STOP' AND work_item.status = 'COMPLETED' AND work_item.root_instance_id = command_record.root_instance_id AND EXISTS ( SELECT 1 FROM ifj_instance terminal_instance JOIN ifj_instance terminal_root ON terminal_root.id = command_record.root_instance_id WHERE terminal_instance.id = command_record.instance_id AND terminal_instance.status IN ('SUCCESS', 'FAILED', 'STOPPED', 'TIMED_OUT', 'SKIPPED') AND terminal_root.status IN ('SUCCESS', 'FAILED', 'STOPPED', 'TIMED_OUT', 'SKIPPED') AND terminal_instance.execution_fence = command_record.processing_fence AND terminal_root.execution_fence = command_record.processing_fence ) )
)

MERGE INTO ifj_runtime_command command_record USING ( SELECT command_record.ROWID AS target_rowid FROM ifj_runtime_command command_record, ifj_trigger_work_item work_item WHERE work_item.trigger_id = command_record.trigger_id AND command_record.request_id = #{requestId} AND command_record.status = 'PROCESSING' AND command_record.processing_token = #{processingToken} AND command_record.processing_fence = #{fenceToken} AND work_item.fence_token = command_record.processing_fence AND ( (work_item.status = 'CLAIMED' AND work_item.lease_owner = command_record.processing_owner AND work_item.lease_deadline > CAST(SYS_EXTRACT_UTC(SYSTIMESTAMP) AS TIMESTAMP(3)))
OR ( command_record.command_type = 'STOP' AND work_item.status = 'COMPLETED' AND work_item.root_instance_id = command_record.root_instance_id AND EXISTS ( SELECT 1 FROM ifj_instance terminal_instance CROSS JOIN ifj_instance terminal_root WHERE terminal_root.id = command_record.root_instance_id AND terminal_instance.id = command_record.instance_id AND terminal_instance.status IN ('SUCCESS', 'FAILED', 'STOPPED', 'TIMED_OUT', 'SKIPPED') AND terminal_root.status IN ('SUCCESS', 'FAILED', 'STOPPED', 'TIMED_OUT', 'SKIPPED') AND terminal_instance.execution_fence = command_record.processing_fence AND terminal_root.execution_fence = command_record.processing_fence ) )
) ) source ON (command_record.ROWID = source.target_rowid) WHEN MATCHED THEN UPDATE SET status = #{status}, result_message = #{resultMessage}, processing_owner = NULL, processing_token = NULL, processing_fence = NULL, processed_at = CAST(SYS_EXTRACT_UTC(SYSTIMESTAMP) AS TIMESTAMP(3)), update_time = CAST(SYS_EXTRACT_UTC(SYSTIMESTAMP) AS TIMESTAMP(3))

UPDATE command_record SET status = #{status}, result_message = #{resultMessage}, processing_owner = NULL, processing_token = NULL, processing_fence = NULL, processed_at = SYSUTCDATETIME(), update_time = SYSUTCDATETIME() FROM ifj_runtime_command AS command_record, ifj_trigger_work_item work_item WHERE work_item.trigger_id = command_record.trigger_id AND command_record.request_id = #{requestId} AND command_record.status = 'PROCESSING' AND command_record.processing_token = #{processingToken} AND command_record.processing_fence = #{fenceToken} AND work_item.fence_token = command_record.processing_fence AND ( (work_item.status = 'CLAIMED' AND work_item.lease_owner = command_record.processing_owner AND work_item.lease_deadline > SYSUTCDATETIME())
OR ( command_record.command_type = 'STOP' AND work_item.status = 'COMPLETED' AND work_item.root_instance_id = command_record.root_instance_id AND EXISTS ( SELECT 1 FROM ifj_instance terminal_instance JOIN ifj_instance terminal_root ON terminal_root.id = command_record.root_instance_id WHERE terminal_instance.id = command_record.instance_id AND terminal_instance.status IN ('SUCCESS', 'FAILED', 'STOPPED', 'TIMED_OUT', 'SKIPPED') AND terminal_root.status IN ('SUCCESS', 'FAILED', 'STOPPED', 'TIMED_OUT', 'SKIPPED') AND terminal_instance.execution_fence = command_record.processing_fence AND terminal_root.execution_fence = command_record.processing_fence ) )
)
